// pac_harness.js — node-side PAC execution harness.
//
// Loaded by pac_js_test.go via `node pac_harness.js <pac-file>`.
// Defines a faithful subset of the PAC utility function environment so that
// the rendered PAC's FindProxyForURL runs under node the same way it runs in
// a browser. Reads the rendered PAC from the file path in argv[2], evals it
// into this scope, then reads JSON test cases from stdin (one per line) and
// prints JSON results to stdout.
//
// Each input line: {"url":"...","host":"...","dns":"<ip or null>"}
// Each output line: {"result":"DIRECT" | "PROXY ..." | error}
//
// `dns` controls what dnsResolve(host) returns for that case, so tests can
// simulate "RU IP", "non-RU IP", "IPv6", and "DNS failure (null)" without
// real network resolution.

// pac_harness.js — node-side PAC execution harness.
//
// Loaded by pacjs_test.go via `node pac_harness.js <pac-file>`.
// Defines a faithful subset of the PAC utility function environment so that
// the rendered PAC's FindProxyForURL runs under node the same way it runs in
// a browser. Reads the rendered PAC from the file path in argv[2], evals it
// into the global scope, then reads JSON test cases from stdin and prints
// JSON results to stdout.
//
// NOTE: deliberately NOT 'use strict' — PAC engines are non-strict, and
// strict-mode eval scopes function declarations to the eval call (so
// FindProxyForURL would not leak into our call site). PAC JS is trusted
// (generated by us), so non-strict eval is safe here.

const fs = require('fs');

const pacPath = process.argv[2];
if (!pacPath) {
  process.stderr.write('usage: node pac_harness.js <pac-file>\n');
  process.exit(2);
}

// --- PAC environment shims ---------------------------------------------

// dnsResolve returns the per-test-case value (set by the runner below).
// Default to null (resolution failure) so a case that forgets to set `dns`
// fails loudly rather than silently matching a wrong range.
let currentDns = null;
function dnsResolve(_host) {
  return currentDns;
}

// isPlainHostName: true iff host has no dots.
function isPlainHostName(host) {
  return String(host).indexOf('.') === -1;
}

// dnsResolve is used by isInNet internally in real PAC engines; we resolve
// via currentDns so it agrees with the test's stated IP.
function isInNet(host, base, mask) {
  const ip = resolveToIp(host);
  if (ip === null) return false;
  return (ip & ipToInt(mask)) === (ipToInt(base) & ipToInt(mask));
}

// shExpMatch: glob match. PAC engines implement a limited form: '*' matches
// any sequence. We translate the pattern to a RegExp. The host is matched
// case-insensitively (the PAC lowercases host before calling).
function shExpMatch(host, pattern) {
  const re = new RegExp('^' + pattern.split('*').map(escapeRegex).join('.*') + '$', 'i');
  return re.test(host);
}
function escapeRegex(s) {
  return s.replace(/[.+?^${}()|[\]\\]/g, '\\$&');
}

function ipToInt(ip) {
  const parts = String(ip).split('.');
  if (parts.length !== 4) return -1;
  let n = 0;
  for (let i = 0; i < 4; i++) {
    const o = parseInt(parts[i], 10);
    if (isNaN(o) || o < 0 || o > 255) return -1;
    n = (n * 256) + o;
  }
  return n;
}

function resolveToIp(host) {
  // If host is already a dotted quad, use it; otherwise consult currentDns.
  if (/^\d+\.\d+\.\d+\.\d+$/.test(host)) {
    return ipToInt(host);
  }
  if (currentDns === null) return null;
  return ipToInt(currentDns);
}

// --- Load the rendered PAC --------------------------------------------

const pacSource = fs.readFileSync(pacPath, 'utf8');
// eslint-disable-next-line no-eval
eval(pacSource); // defines FindProxyForURL, RU_RANGES, etc. into this scope.

if (typeof FindProxyForURL !== 'function') {
  process.stderr.write('PAC did not define FindProxyForURL\n');
  process.exit(2);
}

// --- Read cases, run, emit results ------------------------------------

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => { input += chunk; });
process.stdin.on('end', () => {
  const lines = input.split('\n').filter((l) => l.trim().length > 0);
  for (const line of lines) {
    let tc;
    try {
      tc = JSON.parse(line);
    } catch (e) {
      process.stdout.write(JSON.stringify({ error: 'bad test case json: ' + e.message }) + '\n');
      continue;
    }
    currentDns = tc.dns === undefined ? null : tc.dns;
    try {
      const result = FindProxyForURL(tc.url, tc.host);
      process.stdout.write(JSON.stringify({ result: String(result) }) + '\n');
    } catch (e) {
      process.stdout.write(JSON.stringify({ error: String(e && e.message || e) }) + '\n');
    }
  }
});
